// SPDX-License-Identifier: GPL-2.0
/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 *
 * Covers strncasecmp() from lib/string.c: normal ordering, case folding,
 * the len boundary (off-by-one), NUL handling, unsigned char semantics and
 * the sign/magnitude of the returned difference.
 */
#include <kunit/test.h>
#include <linux/array_size.h>
#include <linux/ctype.h>
#include <linux/string.h>
#include <linux/types.h>

static void agent_strncasecmp_equal_strings(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strncasecmp("hello", "hello", 5), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("a", "a", 1), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("", "", 1), 0);
}

static void agent_strncasecmp_zero_len(struct kunit *test)
{
	/* len == 0 compares nothing, so even differing strings are equal. */
	KUNIT_EXPECT_EQ(test, strncasecmp("abc", "xyz", 0), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("", "a", 0), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp(NULL, NULL, 0), 0);
}

static void agent_strncasecmp_ordering(struct kunit *test)
{
	KUNIT_EXPECT_LT(test, strncasecmp("abc", "abd", 3), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("abd", "abc", 3), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("abc", "abd", 3), -1);
	KUNIT_EXPECT_EQ(test, strncasecmp("abd", "abc", 3), 1);
	KUNIT_EXPECT_EQ(test, strncasecmp("a", "b", 1), -1);
	KUNIT_EXPECT_EQ(test, strncasecmp("b", "a", 1), 1);
	KUNIT_EXPECT_LT(test, strncasecmp("apple", "banana", 6), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("banana", "apple", 6), 0);
}

static void agent_strncasecmp_case_insensitive(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strncasecmp("HeLLo World", "hello WORLD", 11), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("ABC", "abc", 3), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("abc", "ABC", 3), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("A", "a", 1), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("Z", "z", 1), 0);
}

static void agent_strncasecmp_all_letters_fold(struct kunit *test)
{
	char lower[2] = { 0, 0 };
	char upper[2] = { 0, 0 };
	int c;

	for (c = 'a'; c <= 'z'; c++) {
		lower[0] = (char)c;
		upper[0] = (char)(c - 'a' + 'A');
		KUNIT_ASSERT_EQ(test, strncasecmp(lower, upper, 1), 0);
		KUNIT_ASSERT_EQ(test, strncasecmp(upper, lower, 1), 0);
	}
}

static void agent_strncasecmp_non_letter_boundaries(struct kunit *test)
{
	/* Characters just outside 'A'..'Z' and 'a'..'z' must not be folded. */
	KUNIT_EXPECT_EQ(test, strncasecmp("`", "A", 1), -1);	/* 0x60 vs 'a' */
	KUNIT_EXPECT_EQ(test, strncasecmp("A", "`", 1), 1);
	KUNIT_EXPECT_EQ(test, strncasecmp("@", "`", 1), -32);	/* 0x40 vs 0x60 */
	KUNIT_EXPECT_EQ(test, strncasecmp("[", "{", 1), -32);	/* 0x5b vs 0x7b */
	KUNIT_EXPECT_EQ(test, strncasecmp("Z", "[", 1), 31);	/* 'z' vs 0x5b */
	KUNIT_EXPECT_EQ(test, strncasecmp("{", "Z", 1), 1);	/* 0x7b vs 'z' */
	KUNIT_EXPECT_EQ(test, strncasecmp("9", ":", 1), -1);
	KUNIT_EXPECT_EQ(test, strncasecmp("0", "/", 1), 1);
	KUNIT_EXPECT_NE(test, strncasecmp("@", "a", 1), 0);
	KUNIT_EXPECT_NE(test, strncasecmp("{", "z", 1), 0);
}

static void agent_strncasecmp_len_boundary(struct kunit *test)
{
	/* Mismatch at index 3 must be ignored when len == 3 ... */
	KUNIT_EXPECT_EQ(test, strncasecmp("abcX", "abcY", 3), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("abc", "abd", 2), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("a", "A", 1), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("ab", "AC", 1), 0);
	/* ... and detected when len == 4. */
	KUNIT_EXPECT_LT(test, strncasecmp("abcX", "abcY", 4), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("abcd", "abce", 4), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("abcd", "abce", 5), 0);
}

static void agent_strncasecmp_mismatch_last_compared(struct kunit *test)
{
	/* The final character inside len must still be compared. */
	KUNIT_EXPECT_EQ(test, strncasecmp("abcd", "abce", 4), -1);
	KUNIT_EXPECT_EQ(test, strncasecmp("abce", "abcd", 4), 1);
	KUNIT_EXPECT_EQ(test, strncasecmp("xa", "xb", 2), -1);
	KUNIT_EXPECT_EQ(test, strncasecmp("ab", "AC", 2), -1);
}

static void agent_strncasecmp_first_mismatch_wins(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strncasecmp("aXbZ", "AxBz", 4), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("aXbZ", "AxcZ", 4), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("aXcZ", "AxbZ", 4), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("aXcZ", "AxbZ", 2), 0);
}

static void agent_strncasecmp_prefix(struct kunit *test)
{
	/* Shorter string hits NUL: "abc\0" vs "abcd" -> 0 - 'd'. */
	KUNIT_EXPECT_EQ(test, strncasecmp("abc", "abcdef", 6), -100);
	KUNIT_EXPECT_EQ(test, strncasecmp("abcdef", "abc", 6), 100);
	KUNIT_EXPECT_EQ(test, strncasecmp("abc", "abcdef", 3), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("ABC", "abcdef", 3), 0);
}

static void agent_strncasecmp_empty_strings(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strncasecmp("", "", 5), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("", "a", 1), -97);
	KUNIT_EXPECT_EQ(test, strncasecmp("a", "", 1), 97);
	KUNIT_EXPECT_EQ(test, strncasecmp("", "a", 0), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("", "A", 1), -97);
}

static void agent_strncasecmp_len_exceeds_strings(struct kunit *test)
{
	/* Must stop at the terminating NUL and never read past it. */
	KUNIT_EXPECT_EQ(test, strncasecmp("abc", "ABC", 100), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("abc", "abc", (size_t)-1), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("abc", "abd", 100), 0);
}

static void agent_strncasecmp_embedded_nul(struct kunit *test)
{
	/* A NUL stops the comparison, so bytes after it are ignored. */
	KUNIT_EXPECT_EQ(test, strncasecmp("ab\0cd", "ab\0ce", 5), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("ab\0x", "AB\0y", 4), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("ab\0", "ab", 3), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("ab", "ab\0", 3), 0);
}

static void agent_strncasecmp_unsigned_chars(struct kunit *test)
{
	/* Characters compare as unsigned char, so 0xff > 0x01. */
	KUNIT_EXPECT_EQ(test, strncasecmp("\xff", "\x01", 1), 254);
	KUNIT_EXPECT_EQ(test, strncasecmp("\x01", "\xff", 1), -254);
	KUNIT_EXPECT_GT(test, strncasecmp("\x80", "\x7f", 1), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("\x7f", "\x80", 1), 0);
}

static void agent_strncasecmp_high_bit_not_folded(struct kunit *test)
{
	/* Latin-1 'A' with grave (0xc0) and 'a' with grave (0xe0) are not ASCII letters. */
	KUNIT_EXPECT_NE(test, strncasecmp("\xc0", "\xe0", 1), 0);
	KUNIT_EXPECT_NE(test, strncasecmp("\xe0", "\xc0", 1), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("\xc0", "\xc0", 1), 0);
}

static void agent_strncasecmp_return_is_difference(struct kunit *test)
{
	/* Return value is the difference of the folded characters. */
	KUNIT_EXPECT_EQ(test, strncasecmp("A", "c", 1), -2);
	KUNIT_EXPECT_EQ(test, strncasecmp("C", "a", 1), 2);
	KUNIT_EXPECT_EQ(test, strncasecmp("ABC", "abd", 3), -1);
	KUNIT_EXPECT_EQ(test, strncasecmp("AZ", "az", 2), 0);
}

static void agent_strncasecmp_symmetry(struct kunit *test)
{
	static const char * const strs[] = {
		"", "a", "A", "abc", "ABD", "abcdef", "Hello", "hello!", "zz", "Z[",
	};
	size_t i, j;

	for (i = 0; i < ARRAY_SIZE(strs); i++) {
		for (j = 0; j < ARRAY_SIZE(strs); j++) {
			int ab = strncasecmp(strs[i], strs[j], 4);
			int ba = strncasecmp(strs[j], strs[i], 4);

			KUNIT_ASSERT_EQ(test, ab == 0, ba == 0);
			KUNIT_ASSERT_EQ(test, ab < 0, ba > 0);
			KUNIT_ASSERT_EQ(test, ab > 0, ba < 0);
		}
	}
}

/*
 * Build two strings of length n that differ only at index pos, and check
 * the len boundary exactly: len == pos must be equal, len == pos + 1 must
 * not be.
 */
static void agent_strncasecmp_mismatch_each_position(struct kunit *test)
{
	char a[33], b[33];
	size_t n = 32, pos, i;

	for (pos = 0; pos < n; pos++) {
		for (i = 0; i < n; i++) {
			a[i] = 'a' + (char)(i % 26);
			b[i] = 'A' + (char)(i % 26);
		}
		a[n] = b[n] = '\0';
		b[pos] = 'a' + (char)((pos + 1) % 26);	/* differs even after folding */

		KUNIT_ASSERT_EQ(test, strncasecmp(a, b, pos), 0);
		KUNIT_ASSERT_NE(test, strncasecmp(a, b, pos + 1), 0);
		KUNIT_ASSERT_EQ(test, strncasecmp(a, b, n), strncasecmp(a, b, pos + 1));
	}
}

static void agent_strncasecmp_long_strings(struct kunit *test)
{
	char a[257], b[257];
	size_t i;

	for (i = 0; i < 256; i++) {
		a[i] = (i & 1) ? 'q' : 'Q';
		b[i] = (i & 1) ? 'Q' : 'q';
	}
	a[256] = b[256] = '\0';

	KUNIT_EXPECT_EQ(test, strncasecmp(a, b, 256), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp(a, b, 257), 0);

	b[255] = 'r';
	KUNIT_EXPECT_EQ(test, strncasecmp(a, b, 255), 0);
	KUNIT_EXPECT_LT(test, strncasecmp(a, b, 256), 0);
	KUNIT_EXPECT_GT(test, strncasecmp(b, a, 256), 0);
}

static struct kunit_case agent_test_cases[] = {
	KUNIT_CASE(agent_strncasecmp_equal_strings),
	KUNIT_CASE(agent_strncasecmp_zero_len),
	KUNIT_CASE(agent_strncasecmp_ordering),
	KUNIT_CASE(agent_strncasecmp_case_insensitive),
	KUNIT_CASE(agent_strncasecmp_all_letters_fold),
	KUNIT_CASE(agent_strncasecmp_non_letter_boundaries),
	KUNIT_CASE(agent_strncasecmp_len_boundary),
	KUNIT_CASE(agent_strncasecmp_mismatch_last_compared),
	KUNIT_CASE(agent_strncasecmp_first_mismatch_wins),
	KUNIT_CASE(agent_strncasecmp_prefix),
	KUNIT_CASE(agent_strncasecmp_empty_strings),
	KUNIT_CASE(agent_strncasecmp_len_exceeds_strings),
	KUNIT_CASE(agent_strncasecmp_embedded_nul),
	KUNIT_CASE(agent_strncasecmp_unsigned_chars),
	KUNIT_CASE(agent_strncasecmp_high_bit_not_folded),
	KUNIT_CASE(agent_strncasecmp_return_is_difference),
	KUNIT_CASE(agent_strncasecmp_symmetry),
	KUNIT_CASE(agent_strncasecmp_mismatch_each_position),
	KUNIT_CASE(agent_strncasecmp_long_strings),
	{}
};

static struct kunit_suite agent_test_suite = {
	.name = "agent_test",
	.test_cases = agent_test_cases,
};
kunit_test_suite(agent_test_suite);

MODULE_LICENSE("GPL");
